## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;
    localparam int CLK_PERIOD = 8;
    localparam logic [15:0] PRESCALE = 16'd5;
    localparam int BIT_CLKS = 40; // PRESCALE * 8

    logic        clk = 1'b0;
    logic        rst = 1'b0;
    logic        rxd = 1'b1;
    logic        m_axis_tready = 1'b0;
    logic [7:0]  s_axis_tdata = 8'h00;
    logic        s_axis_tvalid = 1'b0;
    logic [15:0] prescale = PRESCALE;
    wire [7:0]   m_axis_tdata;
    wire         m_axis_tvalid;
    wire         s_axis_tready;
    wire         txd;
    wire         tx_busy;
    wire         rx_busy;
    wire         rx_overrun_error;
    wire         rx_frame_error;

    always #(CLK_PERIOD / 2) clk = ~clk;

    uart dut (
        .clk(clk),
        .rst(rst),
        .s_axis_tdata(s_axis_tdata),
        .s_axis_tvalid(s_axis_tvalid),
        .s_axis_tready(s_axis_tready),
        .m_axis_tdata(m_axis_tdata),
        .m_axis_tvalid(m_axis_tvalid),
        .m_axis_tready(m_axis_tready),
        .rxd(rxd),
        .txd(txd),
        .tx_busy(tx_busy),
        .rx_busy(rx_busy),
        .rx_overrun_error(rx_overrun_error),
        .rx_frame_error(rx_frame_error),
        .prescale(prescale)
    );

    // Monitor for debugging
    always @(posedge clk) begin
        if (!rst) begin
            if (rx_frame_error)
                $display("T=%0t: FRAME_ERROR tvalid=%b tdata=0x%02h tready=%b",
                         $time, m_axis_tvalid, m_axis_tdata, m_axis_tready);
            if (rx_overrun_error)
                $display("T=%0t: OVERRUN tvalid=%b tdata=0x%02h tready=%b",
                         $time, m_axis_tvalid, m_axis_tdata, m_axis_tready);
        end
    end

    task automatic wait_clks(input int n);
        repeat (n) @(negedge clk);
    endtask

    task automatic do_reset();
        rst = 1'b1; wait_clks(5);
        rst = 1'b0; wait_clks(5);
    endtask

    // Send a well-formed 8N1 frame (LSB first), each bit BIT_CLKS clocks
    task automatic uart_send_good(input logic [7:0] b);
        rxd = 1'b0; wait_clks(BIT_CLKS);          // start
        for (int i = 0; i < 8; i++) begin
            rxd = b[i]; wait_clks(BIT_CLKS);       // data
        end
        rxd = 1'b1; wait_clks(BIT_CLKS);          // stop
    endtask

    // Send a frame with a bad stop bit (low) to trigger frame_error
    task automatic uart_send_bad();
        rxd = 1'b0; wait_clks(BIT_CLKS);          // start
        for (int i = 0; i < 8; i++) begin
            rxd = 1'b0; wait_clks(BIT_CLKS);       // data (don't care)
        end
        rxd = 1'b0; wait_clks(BIT_CLKS);          // bad stop (low)
        rxd = 1'b1; wait_clks(BIT_CLKS);          // idle gap
    endtask

    initial begin
        do_reset();
        // m_axis_tready stays 0 (back-pressure) for the entire test

        // 1) Deliver 8'h3C — stays pending because m_axis_tready=0
        uart_send_good(8'h3C);
        wait_clks(10);

        // 2) Frame error while 8'h3C is held under back-pressure
        //    This sets st=1 in cov_R26
        uart_send_bad();
        wait_clks(10);

        // 3) Good frame 8'hA5 overruns the pending 8'h3C
        //    overrun_error pulses, m_axis_tdata changes 8'h3C -> 8'hA5
        uart_send_good(8'hA5);
        wait_clks(20);

        $display("PASS: R26 stimulus completed");
        $finish;
    end

    initial begin
        #1ms;
        $display("FAIL: timeout");
        $finish;
    end

endmodule
```

